package com.ben.csp.radiology;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Loads the REKORD layer-3 source term: what fraction of each nuclide left the
 * building, as a range rather than a number.
 *
 * <p>The data file is generated by {@code tools/radiology/build_source_term.py}.
 * The released activities are quoted from IAEA Pub1239 Table 3.1; the release
 * fractions are that activity divided by the layer-2 core activity. Nothing is
 * fitted, and where a fraction cannot be derived the record says so instead of
 * carrying a plausible-looking number.
 *
 * <p>Two invariants are enforced on load, because both are ways this layer could
 * silently lie. A release fraction must lie in [0, 1]: a value above 1 means the
 * denominator is wrong, and quoting it would hide a layer-2 defect behind a
 * number that looks like a measurement. And a record whose status says its
 * fraction could not be derived must not carry one, so a consumer cannot read a
 * refused entry as if it were a result.
 */
public final class SourceTermLoader {

    public static final String RESOURCE = "/data/csp/radiology/source-term.json";

    private static final List<String> PROBLEMS = new ArrayList<>();
    private static boolean loaded;

    private SourceTermLoader() {}

    /** The loaded source term, keyed by nuclide symbol ("Cs137"). */
    public static Map<String, ReleaseEntry> nuclides() {
        load();
        return Collections.unmodifiableMap(SourceTerm.INSTANCE.nuclides);
    }

    /** Records the loader refused, with the reason. Empty is the only good value. */
    public static List<String> problems() {
        load();
        return Collections.unmodifiableList(PROBLEMS);
    }

    /** The fuel-particle release fraction, the anchor for every refractory nuclide. */
    public static FuelFraction fuelFraction() {
        load();
        return SourceTerm.INSTANCE.fuel;
    }

    /** Nuclides whose fraction was refused, keyed to the reason. */
    public static Map<String, String> refused() {
        load();
        Map<String, String> out = new LinkedHashMap<>();
        for (Map.Entry<String, ReleaseEntry> e : nuclides().entrySet()) {
            if (!e.getValue().fractionDerived()) {
                out.put(e.getKey(), e.getValue().fractionStatus());
            }
        }
        return out;
    }

    /** Total quoted released activity over every nuclide in the table, in PBq. */
    public static double totalReleasedPbq() {
        double sum = 0.0;
        for (ReleaseEntry e : nuclides().values()) {
            sum += e.releasedPbq();
        }
        return sum;
    }

    private static void load() {
        if (loaded) {
            return;
        }
        loaded = true;
        try (InputStream in = SourceTermLoader.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                PROBLEMS.add("resource not found: " + RESOURCE);
                return;
            }
            JsonObject root = JsonParser.parseReader(
                new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
            readFuelFraction(root);
            readNuclides(root);
        } catch (Exception e) {
            PROBLEMS.add("failed to read " + RESOURCE + ": " + e);
        }
    }

    private static void readFuelFraction(JsonObject root) {
        JsonObject f = root.getAsJsonObject("_fuelReleaseFraction");
        if (f == null) {
            PROBLEMS.add("no _fuelReleaseFraction block");
            return;
        }
        SourceTerm.INSTANCE.fuel = new FuelFraction(
            f.get("central").getAsDouble(),
            f.get("low").getAsDouble(),
            f.get("high").getAsDouble(),
            f.has("earlierEstimate") ? f.get("earlierEstimate").getAsDouble() : Double.NaN);
    }

    private static void readNuclides(JsonObject root) {
        JsonObject nucs = root.getAsJsonObject("nuclides");
        if (nucs == null) {
            PROBLEMS.add("no nuclides block");
            return;
        }
        for (Map.Entry<String, JsonElement> e : nucs.entrySet()) {
            String symbol = e.getKey();
            JsonObject o = e.getValue().getAsJsonObject();

            double released = o.get("releasedPbq").getAsDouble();
            String status = o.has("fractionStatus")
                ? o.get("fractionStatus").getAsString() : "missing-status";
            Double fraction = o.has("releaseFraction") && !o.get("releaseFraction").isJsonNull()
                ? o.get("releaseFraction").getAsDouble() : null;
            Double corePbq = o.has("coreActivityPbq") && !o.get("coreActivityPbq").isJsonNull()
                ? o.get("coreActivityPbq").getAsDouble() : null;
            String note = o.has("note") ? o.get("note").getAsString() : "";

            boolean derived = "derived".equals(status);

            // A fraction above 1 is not a small error; it means the core
            // activity it was divided by is wrong. Refuse to load it as data.
            if (fraction != null && (fraction < 0.0 || fraction > 1.0)) {
                PROBLEMS.add(symbol + ": release fraction " + fraction
                    + " outside [0,1] -- denominator is wrong, not the release");
                continue;
            }
            // A refused entry must not also carry a number.
            if (!derived && fraction != null) {
                PROBLEMS.add(symbol + ": status '" + status
                    + "' but a release fraction is present");
                continue;
            }
            if (derived && fraction == null) {
                PROBLEMS.add(symbol + ": status 'derived' but no release fraction");
                continue;
            }

            SourceTerm.INSTANCE.nuclides.put(symbol, new ReleaseEntry(
                symbol, released, fraction, corePbq, status, derived,
                o.has("volatilityClass") ? o.get("volatilityClass").getAsString() : "",
                o.has("qualifier") && !o.get("qualifier").isJsonNull()
                    ? o.get("qualifier").getAsString() : "",
                note));
        }
    }

    /** One nuclide's release: the quoted activity and, if derivable, the fraction. */
    public record ReleaseEntry(
        String symbol,
        double releasedPbq,
        Double releaseFraction,
        Double coreActivityPbq,
        String fractionStatus,
        boolean fractionDerived,
        String volatilityClass,
        String qualifier,
        String note
    ) {
        /** Released activity in becquerel. */
        public double releasedBq() {
            return releasedPbq * 1e15;
        }
    }

    /** The fuel-particle release fraction and its bounds. */
    public record FuelFraction(double central, double low, double high, double earlierEstimate) {
        /** True when the earlier (INSAG-1 era) estimate is roughly double this one. */
        public boolean wasRevisedDownByAboutHalf() {
            return !Double.isNaN(earlierEstimate) && earlierEstimate > high;
        }
    }

    private static final class SourceTerm {
        static final SourceTerm INSTANCE = new SourceTerm();
        final Map<String, ReleaseEntry> nuclides = new LinkedHashMap<>();
        FuelFraction fuel = new FuelFraction(Double.NaN, Double.NaN, Double.NaN, Double.NaN);
    }
}
